CREATE TABLE IF NOT EXISTS profile(id INTEGER PRIMARY KEY CHECK(id=1),body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,totp_secret TEXT NOT NULL,last_totp_step INTEGER NOT NULL DEFAULT 0,role TEXT NOT NULL CHECK(role IN ('admin','technician')),disabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS devices(id TEXT PRIMARY KEY,name TEXT NOT NULL,rustdesk_id TEXT NOT NULL UNIQUE,token_hash TEXT NOT NULL UNIQUE,unattended INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL CHECK(state IN ('pending','approved','revoked')),group_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS group_access(group_id TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id),PRIMARY KEY(group_id,user_id));
CREATE TABLE IF NOT EXISTS grants(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),device_id TEXT NOT NULL REFERENCES devices(id),body TEXT NOT NULL,expires_at INTEGER NOT NULL,claimed INTEGER NOT NULL DEFAULT 0,closed INTEGER NOT NULL DEFAULT 0,lease_until INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,at INTEGER NOT NULL,actor TEXT NOT NULL,event TEXT NOT NULL,target TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS releases(id TEXT PRIMARY KEY,body TEXT NOT NULL,envelope TEXT NOT NULL,approved INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS workers(id TEXT PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE,disabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS builds(id TEXT PRIMARY KEY,body TEXT NOT NULL,state TEXT NOT NULL,worker TEXT NOT NULL DEFAULT '',claimed_at INTEGER NOT NULL DEFAULT 0,result TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS group_permissions(group_id TEXT PRIMARY KEY,body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS device_consent_revisions(device_id TEXT PRIMARY KEY REFERENCES devices(id),revision INTEGER NOT NULL);
PRAGMA user_version=1;
